canonical_sig:
∀ {α : Type u_1} {β : Type u_2} [inst : MeasurableSpace α]
  [inst_1 : MeasurableSpace β] {μ : MeasureTheory.Measure α} {ν : MeasureTheory.Measure β}
  [inst_2 : MeasureTheory.SFinite ν] [inst_3 : MeasureTheory.IsProbabilityMeasure μ], Eq (μ.prod ν).snd ν

∀ {𝕜 : Type u_1} {E : Type u_2} {M : Type u_3} {H : Type u_4}
  [inst : NontriviallyNormedField 𝕜] [inst_1 : NormedAddCommGroup E] [inst_2 : NormedSpace 𝕜 E]
  [inst_3 : TopologicalSpace H] [inst_4 : TopologicalSpace M] (f : PartialHomeomorph M H) {I : ModelWithCorners 𝕜 E H}
  {y : M},
  Membership.mem f.source y →
    Eq (Filter.map (↑(f.extend I).symm) (nhdsWithin (↑(f.extend I) y) (Set.range ↑I))) (nhds y)

∀ {R : Type u_1} {S : Type u_2} [inst : CommRing R] [inst_1 : CommRing S] {n : Type u_3}
  [inst_2 : DecidableEq n] [inst_3 : Fintype n] (M : Matrix n n R) (f : RingHom R S),
  Eq (M.map ⇑f).charpoly (Polynomial.map f M.charpoly)

∀ {𝕜 : Type u_1} [inst : NontriviallyNormedField 𝕜] {E : Type u_2}
  [inst_1 : NormedAddCommGroup E] [inst_2 : NormedSpace 𝕜 E] {H : Type u_3} [inst_3 : TopologicalSpace H]
  {I : ModelWithCorners 𝕜 E H} {M : Type u_4} [inst_4 : TopologicalSpace M] [inst_5 : ChartedSpace H M] {E' : Type u_5}
  [inst_6 : NormedAddCommGroup E'] [inst_7 : NormedSpace 𝕜 E'] {H' : Type u_6} [inst_8 : TopologicalSpace H']
  {I' : ModelWithCorners 𝕜 E' H'} {M' : Type u_7} [inst_9 : TopologicalSpace M'] [inst_10 : ChartedSpace H' M']
  {F' : Type u_8} [inst_11 : NormedAddCommGroup F'] [inst_12 : NormedSpace 𝕜 F'] {G' : Type u_9}
  [inst_13 : TopologicalSpace G'] {J' : ModelWithCorners 𝕜 F' G'} {N' : Type u_10} [inst_14 : TopologicalSpace N']
  [inst_15 : ChartedSpace G' N'] {s : Set M} {x : M} {n : ENat} {f : M → M'} {g : M → N'},
  ContMDiffWithinAt I I' n f s x →
    ContMDiffWithinAt I J' n g s x → ContMDiffWithinAt I (I'.prod J') n (fun x => { fst := f x, snd := g x }) s x

∀ {ι : Type u_1} {α : Type u_2} {β : Type u_3}
  [uα : UniformSpace α] [uβ : UniformSpace β] {l : Filter ι} [inst : l.NeBot] {F : ι → β → α} {f : β → α},
  Filter.Tendsto F l (nhds f) → UniformEquicontinuous F → UniformContinuous f

∀ {Ω : Type u_1} {E : Type u_2} [inst : MeasurableSpace E]
  {m : MeasurableSpace Ω} {ℙ : MeasureTheory.Measure Ω} {μ : MeasureTheory.Measure E} {X : Ω → E}
  [inst_1 : MeasureTheory.HasPDF X ℙ μ], Eq (MeasureTheory.lintegral μ fun x => MeasureTheory.pdf X ℙ μ x) (ℙ Set.univ)

∀ {α : Type u_1} {β : Type u_2} {m : MeasurableSpace α}
  {μ ν : MeasureTheory.Measure α} [inst : NormedAddCommGroup β] {f : α → β},
  MeasureTheory.Integrable f μ → MeasureTheory.Integrable f ν → MeasureTheory.Integrable f (HAdd.hAdd μ ν)

∀ (R : Type u_1) [inst : Semiring R] (p q : Polynomial R) {S : Type u_2}
  [inst_1 : NonAssocSemiring S] [inst_2 : Module R S] [inst_3 : Pow S Nat] (x : S) [inst_4 : NatPowAssoc S]
  [inst_5 : IsScalarTower R S S] [inst_6 : SMulCommClass R S S], Eq ((p.comp q).smeval x) (p.smeval (q.smeval x))

∀ {𝕜 : Type u_2} [inst : NontriviallyNormedField 𝕜] {F : Type u_1}
  [inst_1 : NormedAddCommGroup F] [inst_2 : NormedSpace 𝕜 F] {f₂ : 𝕜 → F},
  Iff (ContDiff 𝕜 (↑Top.top) f₂) (And (Differentiable 𝕜 f₂) (ContDiff 𝕜 (↑Top.top) (deriv f₂)))

∀ {α : Type u_2} {m : Type u_3} {R : Type u_1} {M : Matrix m m R} {b : m → α}
  [inst : CommRing R] [inst_1 : DecidableEq m] [inst_2 : Fintype m] [inst_3 : DecidableEq α] [inst_4 : Fintype α]
  [inst_5 : LinearOrder α], M.BlockTriangular b → Eq M.det (Finset.univ.prod fun k => (M.toSquareBlock b k).det)

∀ {n : Type u_2} [inst : DecidableEq n] [inst_1 : Fintype n] {R : Type u_1}
  [inst_2 : CommRing R] (A : Matrix n n R) {i j : n},
  Ne i j → Eq (A.updateCol i fun k => HAdd.hAdd (A k i) (A k j)).det A.det
